package com.orderflow;
import org.junit.jupiter.api.*;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.orderflow.Contracts.*;

@SpringBootTest(properties={"spring.datasource.url=${TEST_DATABASE_URL:jdbc:h2:mem:operations;MODE=PostgreSQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1;LOCK_TIMEOUT=10000}","orderflow.seed=false","orderflow.expiry-worker=false"})
class OperationsTests {
 @Autowired OperationsService service;@Autowired JdbcTemplate db;
 String warehouse,product;
 @BeforeEach void reset(){for(String table:List.of("return_lines","returns","payment_events","idempotency_keys","activity","stock_movements","order_lines","orders","inventory","products","warehouses"))db.update("DELETE FROM "+table);warehouse=(String)service.createWarehouse(new WarehouseInput("Test warehouse","Hong Kong")).get("id");product=(String)service.createProduct(new ProductInput("TEST-001","Test headphones","Audio",1299)).get("id");service.receive(new StockInput(warehouse,product,10,"Opening test stock"),"opening-test-stock");}
 OrderInput input(int quantity){return new OrderInput("Test customer",warehouse,List.of(new LineInput(product,quantity)));}
 Map<String,Object> stock(){return service.inventory().getFirst();}
 Map<String,Object> paid(int quantity){var o=service.createOrder(input(quantity),"order-paid-"+quantity);service.payment(new PaymentInput("payment-paid-"+quantity,(String)o.get("id"),OperationsService.number(o,"total_cents"),"SUCCEEDED"));return service.order((String)o.get("id"));}
 @SuppressWarnings("unchecked")String line(Map<String,Object> order){return (String)((List<Map<String,Object>>)order.get("lines")).getFirst().get("id");}
 @Test void reservationsSeparateAvailableFromPhysicalStock(){var order=service.createOrder(input(3),"order-reservation");assertEquals("RESERVED",order.get("status"));assertEquals(10,OperationsService.number(stock(),"on_hand"));assertEquals(3,OperationsService.number(stock(),"reserved"));assertEquals(7,OperationsService.number(stock(),"available"));assertEquals(3897,OperationsService.number(order,"total_cents"));}
 @Test void repeatedOrderRequestsAreIdempotentAndChangedPayloadsConflict(){var first=service.createOrder(input(2),"same-order-request");var second=service.createOrder(input(2),"same-order-request");assertEquals(first.get("id"),second.get("id"));assertEquals(1,service.orders().size());assertThrows(BusinessException.class,()->service.createOrder(input(3),"same-order-request"));assertEquals(2,OperationsService.number(stock(),"reserved"));}
 @Test void twoBuyersCannotReserveTheLastUnit()throws Exception{
  db.update("UPDATE inventory SET on_hand=1");var gate=new CountDownLatch(1);
  try(var workers=Executors.newFixedThreadPool(2)){
   var a=workers.submit(()->attempt(gate,"buyer-request-a"));var b=workers.submit(()->attempt(gate,"buyer-request-b"));gate.countDown();var outcomes=List.of(a.get(15,TimeUnit.SECONDS),b.get(15,TimeUnit.SECONDS));assertEquals(1,outcomes.stream().filter(i->i==201).count());assertEquals(1,outcomes.stream().filter(i->i==409).count());
  }
  assertEquals(1,service.orders().size());assertEquals(1,OperationsService.number(stock(),"reserved"));assertEquals(0,OperationsService.number(stock(),"available"));
 }
 private int attempt(CountDownLatch gate,String key)throws Exception{gate.await();try{service.createOrder(input(1),key);return 201;}catch(BusinessException e){return e.status();}}
 @Test void simultaneousDeliveryOfSameOrderRequestCreatesOnlyOneReservation()throws Exception{
  var gate=new CountDownLatch(1);try(var workers=Executors.newFixedThreadPool(2)){Callable<Object> task=()->{gate.await();return service.createOrder(input(2),"same-concurrent-key").get("id");};var a=workers.submit(task);var b=workers.submit(task);gate.countDown();assertEquals(a.get(15,TimeUnit.SECONDS),b.get(15,TimeUnit.SECONDS));}assertEquals(1,service.orders().size());assertEquals(2,OperationsService.number(stock(),"reserved"));
 }
 @Test void shortageInOneLineDoesNotReserveAnyOtherProduct(){var other=service.createProduct(new ProductInput("TEST-002","Unavailable product","Desk",9900));assertThrows(BusinessException.class,()->service.createOrder(new OrderInput("Buyer",warehouse,List.of(new LineInput(product,2),new LineInput((String)other.get("id"),1))),"partial-shortage-key"));assertEquals(0,service.orders().size());assertEquals(0,db.queryForObject("SELECT SUM(reserved) FROM inventory",Integer.class));}
 @Test void paymentRetriesAndOutOfOrderEventsDoNotDoubleConfirmOrReviveCancellation(){var o=service.createOrder(input(2),"payment-scenario-key");String id=(String)o.get("id");long amount=OperationsService.number(o,"total_cents");var event=new PaymentInput("payment-event-001",id,amount,"SUCCEEDED");assertEquals(false,service.payment(event).get("replayed"));assertEquals(true,service.payment(event).get("replayed"));service.payment(new PaymentInput("payment-event-002",id,amount,"FAILED"));assertEquals("PAID",service.order(id).get("status"));assertEquals(2,OperationsService.number(stock(),"reserved"));assertThrows(BusinessException.class,()->service.payment(new PaymentInput("payment-event-001",id,amount+1,"SUCCEEDED")));
  var cancelled=service.createOrder(input(1),"cancelled-order-key");String c=(String)cancelled.get("id");service.cancel(c);service.cancel(c);service.payment(new PaymentInput("late-payment-event",c,OperationsService.number(cancelled,"total_cents"),"SUCCEEDED"));assertEquals("CANCELLED",service.order(c).get("status"));assertEquals(2,OperationsService.number(stock(),"reserved"));}
 @Test void fulfillmentConsumesStockOnceAndRejectsUnpaidOrders(){var unpaid=service.createOrder(input(1),"unpaid-order-key");assertThrows(BusinessException.class,()->service.fulfill((String)unpaid.get("id")));service.cancel((String)unpaid.get("id"));var o=paid(3);service.fulfill((String)o.get("id"));service.fulfill((String)o.get("id"));assertEquals(7,OperationsService.number(stock(),"on_hand"));assertEquals(0,OperationsService.number(stock(),"reserved"));assertThrows(BusinessException.class,()->service.cancel((String)o.get("id")));}
 @Test void partialReturnsUseOriginalPriceRestockExactlyOnceAndCannotExceedShipment(){var o=paid(3);String id=(String)o.get("id");service.fulfill(id);db.update("UPDATE products SET price_cents=9999 WHERE id=?",product);var request=new ReturnInput("One item returned",List.of(new ReturnLineInput(line(o),1)));var returned=service.returnOrder(id,request,"partial-return-key");assertEquals("PARTIALLY_RETURNED",returned.get("status"));assertEquals(1299,OperationsService.number(returned,"refunded_cents"));assertEquals(8,OperationsService.number(stock(),"on_hand"));service.returnOrder(id,request,"partial-return-key");assertEquals(8,OperationsService.number(stock(),"on_hand"));assertThrows(BusinessException.class,()->service.returnOrder(id,new ReturnInput("Too many",List.of(new ReturnLineInput(line(o),3))),"excess-return-key"));var full=service.returnOrder(id,new ReturnInput("Remaining items returned",List.of(new ReturnLineInput(line(o),2))),"full-return-key");assertEquals("RETURNED",full.get("status"));assertEquals(3897,OperationsService.number(full,"refunded_cents"));assertEquals(10,OperationsService.number(stock(),"on_hand"));}
 @Test void duplicateReceiptsDoNotInflateInventory(){var receipt=new StockInput(warehouse,product,5,"Supplier delivery");service.receive(receipt,"receipt-repeat-key");service.receive(receipt,"receipt-repeat-key");assertEquals(15,OperationsService.number(stock(),"on_hand"));assertThrows(BusinessException.class,()->service.receive(new StockInput(warehouse,product,6,"Supplier delivery"),"receipt-repeat-key"));}
 @Test void stockLedgerReconcilesWithEveryPosition(){var o=paid(2);service.fulfill((String)o.get("id"));service.returnOrder((String)o.get("id"),new ReturnInput("One item returned",List.of(new ReturnLineInput(line(o),1))),"ledger-return-key");assertEquals(OperationsService.number(stock(),"on_hand"),db.queryForObject("SELECT SUM(on_hand_delta) FROM stock_movements",Long.class));assertEquals(OperationsService.number(stock(),"reserved"),db.queryForObject("SELECT SUM(reserved_delta) FROM stock_movements",Long.class));}
}
